using System;
using System.Windows.Forms;
using MySqlConnector;
using BC = BCrypt.Net.BCrypt;
namespace biblioteca_galvao { public partial class Cadastro : Form { public Cadastro() { InitializeComponent(); } private void cadastrarBtn_Click(object sender, EventArgs e) { string email=emailTxt.Text.Trim(), user=userTxt.Text.Trim(), senha=senhaTxt.Text, confSenha=confSenhaTxt.Text; if(email==""||user==""||senha=="") { MessageBox.Show("Preencha todos os campos"); return; } if(senha!=confSenha) { MessageBox.Show("As senhas não coincidem!"); return; } if(senha.Length<6) { MessageBox.Show("A senha deve ter pelo menos 7 caracteres"); return; } try { string senhaHash=BC.HashPassword(senha); using(MySqlConnection conexao=MySqlConnector.Conectar()) { conexao.Open(); string sql="insert into usuario (email, usuario, senha) VALUES (@email, @usuario, @senha)"; using(MySqlCommand comando=new MySqlCommand(sql,conexao)) { comando.Parameters.AddWithValue("@email",email); comando.Parameters.AddWithValue("@usuario",user); comando.Parameters.AddWithValue("@senha",senhaHash); comando.ExecuteNonQuery(); } } MessageBox.Show("Conta cadastrada com sucesso!"); this.Close(); } catch(MySqlException erro) when(erro.Number==1062) { MessageBox.Show("Este email ou usuário já está cadastrado"); } catch(Exception erroGenerico) { MessageBox.Show("Erro ao cadastrar: "+erroGenerico.Message); } } } }